// run_id is threaded forward as a value, never re-derived (D14).
const p   = $input.first().json.output ?? {};
const inp = $('When Executed by Another Workflow').first().json;
const arr = v => Array.isArray(v) ? v.map(s => String(s).trim()).filter(Boolean) : [];

const batch = Number(p.batch_size_l);
return [{ json: {
  run_id:         $('Start run').first().json.run_id,
  question:       String(inp.question ?? ''),
  session_id:     String(inp.session_id ?? '').trim(),
  style:          String(p.style ?? '').trim() || 'beer',
  batch_size_l:   Number.isFinite(batch) && batch > 0 ? Math.min(batch, 1000) : 20,
  target_abv_pct: Number(p.target_abv_pct) > 0 ? Number(p.target_abv_pct) : 0,
  descriptors:    arr(p.descriptors),
  must_include:   arr(p.must_include),
  avoid:          arr(p.avoid),
}}];

const brief = $('Unpack brief').first().json;
const rows  = $('Step 2 · retrieve').first().json.rows ?? [];
const cat   = $input.all().map(i => i.json);

if (!cat.length) throw new Error('brew.f_catalogue returned no ingredients');

const idmap = {};
const passages = rows.map((r, n) => {
  const label = `S${n + 1}`;
  idmap[r.chunk_id] = { label, doc_title: r.doc_title, page: r.page };
  return `[${label}] ${r.doc_title} · ${r.heading}${r.page ? ` · p.${r.page}` : ''}\n${r.text}`;
}).join('\n\n');

// The catalogue is the biggest thing in the prompt, so it carries only the
// columns the model actually chooses on. names[] is kept for `compose`, which
// must print ingredient names it never has to look up itself.
const names = {}, kinds = {}, roles = {};
for (const c of cat) {
  names[c.id] = c.supplier ? `${c.supplier} ${c.name}` : c.name;
  kinds[c.id] = c.kind;
  roles[c.id] = c.role;
}

// Grouped by role, not one flat list. role comes from brew.f_catalogue, derived
// in SQL from published colour -- so "Bohemian Dark Malt" at 6.5 L sits under
// BASE and cannot be picked as a roast malt because of what it is called.
const SECTIONS = [
  ['base',    'BASE MALTS - id | name | ppg | degL'],
  ['caramel', 'CARAMEL & CRYSTAL MALTS (10-199 degL) - id | name | ppg | degL'],
  ['roast',   'ROAST MALTS (>=200 degL) - THE ONLY MALTS THAT MAKE A BEER DARK - id | name | ppg | degL'],
  ['adjunct', 'SUGARS & ADJUNCTS - id | name | ppg | degL'],
  ['hop',     'HOPS - id | name | alpha %'],
];
const catalogue = SECTIONS.map(([role, heading]) => {
  const rows = cat.filter(c => c.role === role).map(c =>
    role === 'hop'
      ? `${c.id} | ${names[c.id]} | ${c.alpha_acid_pct ?? '-'}`
      : `${c.id} | ${names[c.id]} | ${c.potential_ppg ?? '-'} | ${c.color_lovibond ?? '-'}`);
  return rows.length ? `${heading}\n${rows.join('\n')}` : null;
}).filter(Boolean).join('\n\n');


// --- observed practice -------------------------------------------------------
// nlq.cohort_stats for the style the brewer named, rendered as a short table.
// Quartiles, not a lone median: "6.50% of grist (usual range 5.10-7.85)" tells
// the model whether a proportion is settled or a matter of taste, and a bare
// median does not.
//
// ⛔ RUNG 3 AND ABOVE IS DROPPED, NOT CAPTIONED. nlq.find_cohort relaxes when it
// cannot fill the exact request -- at rung 4 the cohort contains NONE of the
// ingredients asked for, and at rung 5 it is a different style altogether.
// Handing that to the model as "what brewers do for this beer" would be the
// fabricated-authority failure with extra steps. Better no block than a wrong
// one: the prompt's own rules stand on their own.
const sb       = $('Style bands').first().json;
const cohort   = sb.cohort ?? null;
const pRows    = sb.practice ?? [];
let practice = '';
let practice_yeasts = [];
if (cohort && cohort.rung <= 2 && pRows.length) {
  const bySec = new Map();
  for (const r of pRows) {
    if (!bySec.has(r.section)) bySec.set(r.section, []);
    bySec.get(r.section).push(r);
  }
  practice_yeasts = (bySec.get('yeast') ?? [])
    .map(r => ({ name: r.item, pct: r.pct_of_cohort, typical: r.typical }));

  const HEAD = { 'grain bill': 'GRAIN BILL', hops: 'HOPS',
                 yeast: 'YEAST', 'other additions': 'OTHER ADDITIONS' };
  const body = Object.entries(HEAD).map(([k, h]) => {
    const rs = bySec.get(k);
    if (!rs || !rs.length) return null;
    return `${h}\n` + rs.map(r => `  ${r.item} — in ${r.pct_of_cohort}% of them, ${r.typical}`).join('\n');
  }).filter(Boolean).join('\n\n');
  practice = `Based on ${cohort.n_recipes} recipes.\n\n${body}`;
}

return [{ json: { ...brief, catalogue, passages, idmap, names, kinds, roles,
                  practice, practice_yeasts, cohort,
                  chunk_ids: rows.map(r => r.chunk_id) } }];

const pack = $('Build propose pack').first().json;
const out  = $input.first().json.output ?? {};

const STAGES = new Set(['mash','boil','whirlpool','dryhop','fermenter','packaging']);
const known   = new Set(Object.keys(pack.names).map(Number));
const catKind = pack.kinds;
const catRole = pack.roles;

// A hallucinated ingredient_id would fail the FK inside f_save_recipe anyway;
// dropping it here means the rest of the recipe still gets built, and the drop
// is reported rather than silently swallowed.
const kept = [], dropped = [], assumed = [];
for (const it of (out.items ?? [])) {
  const id  = Number(it.ingredient_id);
  const qty = Math.round(Number(it.qty_g));
  const stage = String(it.stage ?? 'mash');
  if (!known.has(id))            { dropped.push(`unknown ingredient_id ${it.ingredient_id}`); continue; }
  if (!STAGES.has(stage))        { dropped.push(`${pack.names[id]}: bad stage ${stage}`); continue; }
  if (!Number.isFinite(qty) || qty <= 0) { dropped.push(`${pack.names[id]}: bad qty`); continue; }
  const row = { ingredient_id: id, stage, qty_g: qty };
  const t = Number(it.timing_min);
  if (Number.isFinite(t) && t >= 0) row.timing_min = Math.round(t);
  if (it.notes) row.notes = String(it.notes).slice(0, 120);

  // A boil hop with no stated time computes to IBU 0, because Tinseth's
  // boil-time factor is zero at t=0 -- so 30 g of Fuggles would silently
  // contribute nothing. Hops in the kettle DO bitter; assume a standard 60 min
  // bittering addition and say so, rather than report a bitterness we know is
  // wrong. Measured on run 61, which produced exactly this.
  if (row.timing_min == null && stage === 'boil' && catKind[id] === 'hop') {
    row.timing_min = 60;
    row.notes = (row.notes ? row.notes + ' ' : '') + '(boil time not specified; assumed 60 min)';
    assumed.push(`${pack.names[id]}: no boil time given, assumed 60 min`);
  }
  kept.push(row);
}
if (!kept.length) throw new Error('propose returned no usable items: ' + dropped.join('; '));

// ⛔ THE 15% ROAST CEILING IS ENFORCED HERE, NOT IN THE PROMPT. Two prompt
// versions stated it -- v5 "above 15% it turns acrid", v6 "BOTH ENDS ARE
// BINDING ... a ceiling you never cross, not even when a correction tells you
// the beer came out too pale" -- and the model crossed it anyway in 3 of 6 cases
// on the very next run: 21.8%, 17.6%, 16.0%. Restating a numeric proportion
// more forcefully did not work twice, so it stops being the model's job. This is
// the same move brew.f_catalogue made when malt classification kept going wrong:
// take the judgement out of the model and put it in code that cannot drift.
//
// Ceiling ONLY. There is no floor here on purpose -- a pale style correctly has
// no roast malt at all, and forcing one in would break every beer that is not a
// stout. Colour that lands too LIGHT is the style-band gate's job, because only
// it knows what the style is.
const ROAST_MAX = 0.15;
const grainOf = r => kept.filter(it => ['base','caramel','roast'].includes(catRole[it.ingredient_id]))
                          .reduce((s, it) => s + (r ? (catRole[it.ingredient_id] === r ? it.qty_g : 0) : it.qty_g), 0);
const grainTotal = grainOf(null);
const roastTotal = grainOf('roast');
if (grainTotal > 0 && roastTotal / grainTotal > ROAST_MAX) {
  const target  = grainTotal * ROAST_MAX;
  const factor  = target / roastTotal;
  const freed   = Math.round(roastTotal - target);
  const wasPct  = Math.round(1000 * roastTotal / grainTotal) / 10;
  for (const it of kept) {
    if (catRole[it.ingredient_id] === 'roast') it.qty_g = Math.round(it.qty_g * factor);
  }
  // The grain that comes off the roast malts goes onto the largest base malt, so
  // the grist stays the same size and f_fit_recipe still scales onto the target
  // gravity from the same starting point.
  const base = kept.filter(it => catRole[it.ingredient_id] === 'base')
                   .sort((a, b) => b.qty_g - a.qty_g)[0];
  if (base) base.qty_g += freed;
  assumed.push(`roast malt was ${wasPct}% of the grain bill, above the 15% ceiling; trimmed to 15% and the ${freed} g moved to ${pack.names[base ? base.ingredient_id : 0] || 'the base malt'}`);
}

const att = Number(out.attenuation);
const mash = Number(out.mash_temp_c);
// ⛔ `conflicts` rides the SAME channel as missing ingredients, because that
// channel already reaches the brewer through {{gaps}} in compose. Measured on
// R06: asked for a jet-black stout with no roasted or dark malts, the model
// used 1104 g of Black Malt -- 22.5% of the grist -- and wrote that it used
// none. A contradiction the brewer is never told about is worse than a gap.
const conflicts = (Array.isArray(out.conflicts) ? out.conflicts : [])
  .map(x => `the request contradicts itself: ${String(x).slice(0, 160)}`);
// ⛔ `not_available` arrives as bare nouns -- propose is asked for "an array of
// things the brewer asked for that are not in the catalogue" and answers
// "vanilla". compose used to write that into a sentence; the sheet is rendered
// in code now, so the noun has to arrive as one or it prints as "⚠️  vanilla".
// Measured on recipe 75.
const missing = (Array.isArray(out.not_available) ? out.not_available : [])
  .map(x => `${String(x).slice(0, 80)} is not in the catalogue and was left out`);
const gaps = [...conflicts, ...missing, ...dropped, ...assumed];

return [{ json: {
  ...pack,
  items:        kept,
  dropped,
  assumed,
  gaps,
  rationale:    String(out.rationale ?? ''),
  mash_temp_c:  Number.isFinite(mash) && mash > 30 && mash < 80 ? Math.round(mash) : 67,
  attenuation:  Number.isFinite(att) && att > 0.4 && att < 0.95 ? att : 0.75,
  // A 30% boil-off allowance; only used to gravity-correct hop utilisation.
  boil_volume_l: Math.round(pack.batch_size_l * 1.3 * 10) / 10,
  recipe_name:  [pack.style, pack.must_include.slice(0, 2).join(' & ')]
                  .filter(Boolean).join(' · ').slice(0, 80),
}}];

// ⛔ Nothing between the arithmetic and the brewer ever checked the computed
// figures against the brief, so a recipe that is plainly wrong was saved and
// presented as finished. All four measured, all four handed over as stouts:
// recipe 3 and recipe 5 at SRM 7.0 with no roast malt in the grist at all,
// recipe 10 at SRM 12.8, recipe 16 at SRM 20.2 three times identically. Every
// number needed to catch them was already sitting in `fit.computed`.
//
// The check is arithmetic, never a model. brew.f_compute_recipe exists because
// judgement about numbers belongs in SQL (§7.4), and a model marking its own
// homework would hand it straight back. The bands are what BJCP and BA publish
// (ref.f_style_bands) and the ABV the brewer actually asked for. Nothing here
// invents a target: no band, no opinion, and the recipe goes through.
const v     = $('Validate proposal').first().json;
const fit   = $input.first().json.fit;
const c     = fit.computed;
const bands = $('Style bands').first().json.bands ?? {};   // {} = style matched nothing
const style = (bands.styles ?? []).join(' / ');

// Every miss is written twice on purpose: once for the model, imperative and
// naming the catalogue section it has to move, and once for the brewer, who is
// owed the number rather than the instruction.
const misses = [];

// ABV — the brewer's own figure is the band. brew.f_fit_to_abv bisects straight
// onto it, so ±0.5% is ten times the fitter's own resolution and a miss means
// the target was UNREACHABLE: the grist could not scale far enough, or the
// unfermentables already overshot it. The published range is used only when the
// brewer named no strength at all, which `Unpack brief` records as 0.
const tgt   = Number(v.target_abv_pct);
const abvLo = tgt > 0 ? tgt - 0.5 : (bands.abv_min ?? null);
const abvHi = tgt > 0 ? tgt + 0.5 : (bands.abv_max ?? null);
const want  = tgt > 0 ? `${tgt}%` : `${abvLo}-${abvHi}%`;
if (abvLo != null && c.abv_pct < abvLo) misses.push({
  model:  `The previous attempt computed ABV ${c.abv_pct}%, against a target of ${want}. Cut the lactose and the caramel malts -- they raise a gravity the yeast cannot reach -- and let the base malt carry the strength.`,
  brewer: `strength came out at ${c.abv_pct}% ABV against a target of ${want}; the unfermentable additions may be crowding out the base malt`,
});
else if (abvHi != null && c.abv_pct > abvHi) misses.push({
  model:  `The previous attempt computed ABV ${c.abv_pct}%, against a target of ${want}. Cut the sugars and the lactose; those are never scaled to hit the target, so they are carrying too much of the gravity.`,
  brewer: `strength came out at ${c.abv_pct}% ABV against a target of ${want}; the sugar and lactose additions are carrying too much of the gravity`,
});

// SRM — the published band only. The brewer never states a colour, and a colour
// target invented here would refuse beers nobody asked to have refused.
//
// ⛔ 10% tolerance on both bounds, and it is not slack -- it is the resolution of
// the instrument. brew.f_compute_recipe estimates colour from malt Lovibond and
// batch volume; the Morey approximation behind that is not accurate to a single
// SRM point, so treating a published bound as exact invents precision the number
// does not carry. Measured: R01 computed SRM 39.3 against a floor of 40 -- a 1.8%
// miss -- and the retry chased it to 19.2% roast malt, past the 15% ceiling the
// propose prompt calls binding, and STILL landed at 39.3. A gate that forces a
// model past its own constraints to close a rounding gap makes recipes worse.
// A genuine failure is nowhere near this tolerance: recipe 3 was SRM 7.0.
const SRM_TOL = 0.10;
const srmFloor = bands.srm_min != null ? bands.srm_min * (1 - SRM_TOL) : null;
const srmCeil  = bands.srm_max != null ? bands.srm_max * (1 + SRM_TOL) : null;
if (srmFloor != null && c.srm < srmFloor) misses.push({
  model:  `The previous attempt computed SRM ${c.srm}. A ${style} is SRM ${bands.srm_min} or darker. Aim for about SRM ${Math.round(bands.srm_min * 1.1)} -- increase the ROAST MALTS fraction by roughly a quarter and no more. ⛔ Overshooting is a failure too: do not double it. Caramel malts add sweetness, not colour.`,
  brewer: `colour came out at SRM ${c.srm} against SRM ${bands.srm_min} or darker for a ${style}; the grist may need more roast malt`,
});
else if (srmCeil != null && c.srm > srmCeil) misses.push({
  model:  `The previous attempt computed SRM ${c.srm}. A ${style} is SRM ${bands.srm_max} or paler. Aim for about SRM ${Math.round(bands.srm_max * 0.9)} -- cut the ROAST MALTS fraction by roughly a quarter, or to none at all if the style calls for none. ⛔ Undershooting is a failure too.`,
  brewer: `colour came out at SRM ${c.srm} against SRM ${bands.srm_max} or paler for a ${style}; the grist may have too much roast malt`,
});

// ⛔ EXACTLY ONE retry, and the flag is `isExecuted` rather than a counter: it is
// a plain lookup in this run's node data, so the second pass through here cannot
// fail to see it and loop the model forever. A second miss is REPORTED, never
// retried again — looping until a 12B passes turns one bad recipe into an
// unbounded run, and obs.runs budgets steps for a reason.
const retried = $('Step 3b · re-propose').isExecuted;
const retry   = misses.length > 0 && !retried;

return [{ json: { ...v, fit, gate: {
  attempt:  retried ? 2 : 1,
  bands,
  computed: { abv_pct: c.abv_pct, srm: c.srm, ibu: c.ibu },
  retry,
  // Only a miss that SURVIVED the retry is the brewer's business; one the retry
  // fixed is obs.steps' business.
  unresolved: retry ? [] : misses.map(m => m.brewer),
  correction: retry
    ? '⛔ THIS IS A SECOND ATTEMPT. Your last grain bill was computed and came out wrong:\n'
      + misses.map(m => m.model).join('\n')
      + '\nFix exactly that, and keep the rest of the grist you already chose.'
    : '',
}}}];

const v     = $('Validate proposal').first().json;
const fit   = $('Fit hops').first().json.fit;   // post-IBU-fit; 'Fit to target' is one step stale
const saved = $input.first().json.saved;
// ⛔ A verifier miss that survived the retry is NOT routed through `compose`.
const gate  = $('Check bands').first().json.gate;

const c = saved.computed;

// --- buckets --------------------------------------------------------------
// kind and role both come from brew.f_catalogue, which derives role in SQL from
// published colour -- so a malt lands in FERMENTABLES because of what it is,
// never because of what it is called.
const GRAIN   = ['base', 'caramel', 'roast'];
const isHop   = it => v.kinds[it.ingredient_id] === 'hop';
const isGrain = it => GRAIN.includes(v.roles[it.ingredient_id]);

// ⛔ Per-item `notes` are deliberately dropped. They are the model's own 12-word
// blurb ("Base malt for rich malt character") and carry nothing the brewer
// cannot see from the line itself. The ONE note that is load-bearing -- the
// assumed 60 min boil time -- is already pushed onto `gaps` by
// `Validate proposal`, so it still reaches the warnings block.
const row = it => ({
  name:       v.names[it.ingredient_id],
  qty_g:      it.qty_g,
  stage:      it.stage,
  timing_min: it.timing_min ?? null,
});

// Grain descending by weight, hops descending by boil time: brew-day order, and
// it makes two runs of the same recipe diffable.
const fermentables = fit.items.filter(isGrain).map(row).sort((a, b) => b.qty_g - a.qty_g);
const grainTotal   = fermentables.reduce((s, r) => s + r.qty_g, 0);
// ⛔ Denominator is base+caramel+roast, NOT every fermentable. That is the same
// denominator scripts/stress/recipe_eval.py uses for roast_pct, so the printed
// percentage and the graded percentage are the same number.
for (const r of fermentables) r.pct = grainTotal ? Math.round(100 * r.qty_g / grainTotal) : 0;

const hops = fit.items.filter(isHop).map(row)
  .sort((a, b) => (b.timing_min ?? -1) - (a.timing_min ?? -1));

const STAGE_ORDER = ['mash', 'boil', 'whirlpool', 'dryhop', 'fermenter', 'packaging'];
const additions = fit.items.filter(it => !isHop(it) && !isGrain(it)).map(row)
  .sort((a, b) => STAGE_ORDER.indexOf(a.stage) - STAGE_ORDER.indexOf(b.stage) || b.qty_g - a.qty_g);

// --- warnings -------------------------------------------------------------
const gaps = [...v.gaps];
const f = fit.ibu_fit;
if (f && f.scaled) gaps.push(`the hop charge as proposed computed to ${Math.round(f.from)} IBU, outside the published band for the style; every hop was scaled by ${f.factor} to bring it in`);
else if (f && !f.scaled && f.reason) gaps.push(f.reason);

// Sorted by label. idmap is keyed by chunk_id, so its natural iteration order
// is insertion order by chunk id -- which printed S3, S8, S5, S6, S7, S1 ... on
// the first end-to-end run. The labels are retrieval rank; print them in it.
const sourceLines = Object.values(v.idmap)
  .sort((a, b) => Number(a.label.slice(1)) - Number(b.label.slice(1)))
  .map(s => `[${s.label}] ${s.doc_title}${s.page ? `, p.${s.page}` : ''}`);

// --- the sheet ------------------------------------------------------------
// Everything below is COMPUTED -- brew.f_compute_recipe or fit.items. None of
// it needs a model, so none of it is asked of one. `Return` renders it.
const sheet = {
  title: { name: v.recipe_name, batch_size_l: c.batch_size_l,
           recipe_id: saved.recipe_id, version: saved.version },
  warnings:     gaps,
  band_miss:    gate.unresolved,
  fermentables, grain_total_g: grainTotal,
  hops, additions,
  // attenuation is propose's own choice and is real; the strains beside it are
  // what brewers of this style actually pitched, from the corpus. Empty when the
  // cohort was relaxed or missing, and `Return` then prints the old honest line.
  yeast:   { attenuation: v.attenuation, observed: v.practice_yeasts ?? [] },
  mash:    { temp_c: v.mash_temp_c, efficiency: 0.72 },
  targets: { og: c.og, fg: c.fg, abv_pct: c.abv_pct, ibu: c.ibu, ebc: c.ebc, srm: c.srm },
  sources: sourceLines,

  // Optional sections. Each is null until something fills it, and `Return`
  // prints no heading for a null. Nothing in brew.* or ref.* holds any of this
  // today -- water chemistry, a pitch schedule and a carbonation level are
  // RETRIEVED and reasoned, not computed, and a recipe run does not do that
  // work. Absent by default is the point: it is what stops the sheet being
  // padded with plausible invented salt additions.
  mash_steps:   null,   // brew.recipes.mash_profile is written {mash_temp_c} only
  boil:         null,   // boil_volume_l + max hop timing_min would fill it
  water:        null,   // brew.recipes.water_profile: column exists, no writer
  fermentation: null,   // no structured source; the Yeast book via retrieval
  packaging:    null,   // no structured source; volumes CO2 / priming sugar
  notes:        null,
};

return [{ json: {
  run_id:   v.run_id,
  question: v.question,
  sheet,
  // compose v5 gets the grain bill for context and the passage TEXT to quote
  // from -- v4 was handed only "[S1] Title, p.12" lines and asked for a
  // technique claim carrying an [S..] label, which is a citation with nothing
  // behind it.
  recipe:   [...fermentables, ...hops, ...additions]
              .map(r => `${r.name} · ${r.qty_g} g · ${r.stage}`).join('\n'),
  passages: v.passages,
  recipe_id: saved.recipe_id,
  version:   saved.version,
  spent: JSON.stringify({ recipe_id: saved.recipe_id, version: saved.version,
                          items: saved.items, scale_factor: fit.scale_factor,
                          gate: { attempt: gate.attempt, unresolved: gate.unresolved } }),
}}];

// === Return ==================================================================
// Body of the `Return` code node. One item, one key -- the toolWorkflow node
// hands the last output to the model.
//
// ⛔ THE SHEET IS RENDERED HERE, NOT COMPOSED. compose v4 carried nine layout
// rules and a 12B dropped the mandatory Sources heading in 3 of 5 measured runs;
// the same node already had to append the band-miss line deterministically for
// exactly that reason. Every value on the sheet is computed, so every value is
// printed by code. The model writes ONE line and it is spliced in below.
function renderSheet(s, technique) {
  const out = [];
  // A section is a function of its data: no data, no heading. Never a heading
  // with "not specified" under it, and never the word "none" anywhere.
  const sec = (heading, rows) => {
    if (!rows || !rows.length) return;
    out.push(heading, ...rows.map(r => `  ${r}`), '');
  };
  const kg  = g => `${(g / 1000).toFixed(2)} kg`;
  // timing and stage read as one phrase -- "60 min boil", "dry hop" -- not as
  // two dot-separated columns, one of which is usually empty.
  const when = r => {
    const stage = r.stage === 'dryhop' ? 'dry hop' : r.stage;
    if (r.timing_min == null) return stage;
    // 0 minutes in the kettle is flameout, which is what a brewer calls it --
    // "Lactose · 800 g · 0 min boil" is the arithmetic showing through.
    if (r.timing_min === 0) return stage === 'boil' ? 'flameout' : stage;
    return `${r.timing_min} min ${stage}`;
  };
  const line = parts => parts.filter(Boolean).join(' · ');

  const t = s.title;
  out.push(line([t.name, `${t.batch_size_l} L`, `recipe #${t.recipe_id} v${t.version}`]), '');

  // Warnings first. A brewer who reads only the top of the sheet must still see
  // that the request contradicted itself or that an ingredient was missing.
  const warn = [
    ...s.warnings.map(w => `⚠️  ${w}`),
    ...(s.band_miss.length
        ? [`⚠️  this recipe did not land inside the published band for the style: ${s.band_miss.join('; ')}`]
        : []),
  ];
  if (warn.length) out.push(...warn, '');

  sec(`FERMENTABLES · ${kg(s.grain_total_g)}`,
      s.fermentables.map(r => line([r.name, `${r.qty_g} g`, `${r.pct}%`])));

  sec(`HOPS · ${s.targets.ibu} IBU`,
      s.hops.map(r => line([r.name, `${r.qty_g} g`, when(r)])));

  sec('ADDITIONS',
      s.additions.map(r => line([r.name, `${r.qty_g} g`, when(r)])));

  // ⛔ brew.ingredients holds 77 fermentables, 72 hops and 1 adjunct -- and no
  // yeast at all. Attenuation is a number `propose` chose and is real; a strain
  // name would be invented. Say which is which rather than print a heading with
  // nothing under it.
  // ⛔ brew.ingredients still holds no yeast, so no strain here is a catalogue
  // pick and none can be saved with the recipe. What the corpus can say is which
  // strains brewers of this style actually used -- observed, not prescribed, and
  // labelled as such on the sheet so it is never read as a catalogue entry.
  sec('YEAST', [
    line([`attenuation ${Math.round(s.yeast.attenuation * 100)}%`,
          'no yeast in the catalogue — pick your own']),
    ...(s.yeast.observed.length
        ? ['commonly used for this style (from 174k homebrew recipes, not a recommendation):',
           ...s.yeast.observed.map(y => `  ${y.name} · ${y.pct}% of them · ${y.typical}`)]
        : []),
  ]);

  sec('MASH', s.mash_steps
      ? s.mash_steps.map(st => line([st.name, `${st.temp_c} °C`, `${st.minutes} min`]))
      : [line([`${s.mash.temp_c} °C`, `${Math.round(s.mash.efficiency * 100)}% efficiency`])]);

  // Optional, and all null today -- see the note in `Build compose vars`.
  sec('BOIL',         s.boil);
  sec('WATER',        s.water);
  sec('FERMENTATION', s.fermentation);
  sec('PACKAGING',    s.packaging);

  const g = s.targets;
  sec('TARGETS', [line([`OG ${g.og.toFixed(3)}`, `FG ${g.fg.toFixed(3)}`, `ABV ${g.abv_pct.toFixed(1)}%`]),
                  line([`IBU ${g.ibu}`, `EBC ${g.ebc}`, `SRM ${g.srm}`])]);

  if (technique) out.push(technique, '');
  sec('NOTES', s.notes);

  // tier2_e2e.py greps for this exact heading.
  if (s.sources.length) out.push('Sources:', ...s.sources);

  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

const c = $('Build compose vars').first().json;

// ⛔ compose v5 asks for one sentence and nothing else, and the whole point of
// this node is that a prompt rule is not a guarantee. Take the first real line,
// drop anything that looks like the model re-printing a section heading, and
// cap it. A runaway costs the sheet nothing because the sheet is already built.
const oneLine = (txt) => {
  const line = String(txt ?? '').split('\n')
    .map(s => s.trim())
    .find(s => s && !/^(sources:|fermentables|hops|additions|yeast|mash|boil|water|fermentation|packaging|targets|notes)\b/i.test(s));
  return line ? line.slice(0, 220) : '';
};
const technique = oneLine($('Step 4 · compose').first().json.output);
return [{ json: { response:
  `${renderSheet(c.sheet, technique)}\n\n(saved as recipe #${c.recipe_id} v${c.version})` } }];
